package com.amora.app;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.webkit.*;import android.widget.*;import org.json.*;
/** The untrusted provider is isolated in a WebView with NO native JavaScript bridge. */
public class YouTubeActivity extends Activity {
 static YouTubeActivity active;WebView web;TextView heading;final Handler handler=new Handler(Looper.getMainLooper());final java.util.concurrent.ExecutorService io=java.util.concurrent.Executors.newSingleThreadExecutor();boolean resumed=false,busy=false;String loaded="",user="";JSONObject latest;long serverOffset=0;
 final Runnable poll=new Runnable(){public void run(){if(!resumed)return;if(!busy&&!user.isEmpty()){busy=true;io.execute(()->{try{JSONObject d=AmoraApi.call(YouTubeActivity.this,new JSONObject().put("action","music"));handler.post(()->{try{apply(d);}catch(Exception e){heading.setText("Escolha uma música do YouTube no Amora.");}});}catch(Exception e){handler.post(()->heading.setText("Sem conexão. Volte ao Amora para tentar novamente."));}finally{handler.post(()->busy=false);}});}handler.postDelayed(this,4000);}};
 @Override public void onCreate(Bundle state){super.onCreate(state);active=this;LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(16,17,38));Button back=new Button(this);back.setText("‹ Voltar ao Amora");back.setAllCaps(false);back.setTextColor(Color.rgb(217,205,255));back.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.rgb(32,26,52)));back.setOnClickListener(v->finish());root.addView(back);heading=new TextView(this);heading.setTextColor(Color.WHITE);heading.setPadding(20,14,20,14);heading.setText("Abrindo a música de vocês…");root.addView(heading);web=new WebView(this);web.setBackgroundColor(Color.BLACK);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.getSettings().setMediaPlaybackRequiresUserGesture(true);web.setWebChromeClient(new WebChromeClient());web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest r){if(!r.isForMainFrame())return false;try{if("https".equals(r.getUrl().getScheme()))startActivity(new Intent(Intent.ACTION_VIEW,r.getUrl()));}catch(Exception ignored){}return true;}});root.addView(web,new LinearLayout.LayoutParams(-1,0,1));TextView note=new TextView(this);note.setTextColor(Color.LTGRAY);note.setPadding(20,12,20,16);note.setText("YouTube · mantenha esta tela aberta. Se o autor impedir a reprodução, escolha outro vídeo. Pode ser necessário tocar no player para liberar o som.");root.addView(note);setContentView(root);root.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets.consumeSystemWindowInsets();});String initial=getIntent().getStringExtra("videoId");if(initial!=null&&initial.matches("[A-Za-z0-9_-]{11}"))loadVideo(initial);try{user=new JSONObject(SecureStore.get(this)).getString("user");}catch(Exception e){user="";}}
 void loadVideo(String id){loaded=id;String html="<!doctype html><title>Amora YouTube</title><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='referrer' content='strict-origin-when-cross-origin'><style>html,body{margin:0;background:#000;height:100%;}#player{width:100%;height:100%;min-height:200px}</style><div id='player'></div><script>var p,changed=false,applying=Date.now()+6000;function onYouTubeIframeAPIReady(){p=new YT.Player('player',{videoId:'"+id+"',playerVars:{playsinline:1,origin:'https://com.amora.app',widget_referrer:'https://com.amora.app'},events:{onStateChange:function(e){if(Date.now()>applying&&[0,1,2].includes(e.data))changed=true;}}});}</script><script src='https://www.youtube.com/iframe_api'></script>";web.loadDataWithBaseURL("https://com.amora.app",html,"text/html","UTF-8","https://com.amora.app/");}
 void apply(JSONObject d)throws Exception{if(!resumed)return;if(!user.equals(new JSONObject(SecureStore.get(this)).getString("user"))){finish();return;}latest=d;serverOffset=java.time.Instant.parse(d.getString("server_time")).toEpochMilli()-System.currentTimeMillis();JSONObject session=d.optJSONObject("session"),track=null;JSONArray queue=d.optJSONArray("queue");for(int i=0;session!=null&&queue!=null&&i<queue.length();i++)if(queue.getJSONObject(i).getString("id").equals(session.optString("track_id")))track=queue.getJSONObject(i);if(track==null||!"youtube".equals(track.getString("provider"))){web.evaluateJavascript("window.p&&p.pauseVideo&&p.pauseVideo()",null);heading.setText("Escolha uma música do YouTube no Amora.");return;}String url=track.getString("url"),id=android.net.Uri.parse(url).getQueryParameter("v");if(id==null||!id.matches("[A-Za-z0-9_-]{11}"))return;heading.setText(track.getString("title"));if(!id.equals(loaded)){loadVideo(id);return;}
 final JSONObject s=session;web.evaluateJavascript("(()=>{if(!window.p||!p.getPlayerState)return null;var d={changed:changed,state:p.getPlayerState(),position:p.getCurrentTime()};changed=false;return JSON.stringify(d)})()",value->{try{if(value==null||value.equals("null")||!resumed)return;JSONObject local=new JSONObject(new JSONArray("["+value+"]").getString(0));if(local.optBoolean("changed")&&local.optInt("state")!=0){io.execute(()->{try{AmoraApi.call(this,new JSONObject().put("action","playback").put("id",s.getString("track_id")).put("playing",local.optInt("state")==1).put("position",local.optDouble("position")).put("revision",s.getInt("revision")));}catch(Exception ignored){}});return;}double pos=s.optDouble("position")+(s.optBoolean("playing")?(System.currentTimeMillis()+serverOffset-java.time.Instant.parse(s.getString("updated_at")).toEpochMilli())/1000.0:0);boolean play=s.optBoolean("playing");web.evaluateJavascript("(()=>{if(!window.p||!p.getPlayerState)return;if(Math.abs(p.getCurrentTime()-"+Math.max(0,Math.min(86400,pos))+")>3||("+play+"&&p.getPlayerState()!==1)||(!"+play+"&&p.getPlayerState()===1))applying=Date.now()+1500;if(Math.abs(p.getCurrentTime()-"+Math.max(0,Math.min(86400,pos))+")>3)p.seekTo("+Math.max(0,Math.min(86400,pos))+",true);if("+play+"&&p.getPlayerState()!==1)p.playVideo();if(!"+play+"&&p.getPlayerState()===1)p.pauseVideo()})()",null);}catch(Exception ignored){}});
 }
 @Override protected void onResume(){super.onResume();resumed=true;web.onResume();handler.post(poll);}
 @Override protected void onPause(){resumed=false;handler.removeCallbacks(poll);web.evaluateJavascript("window.p&&p.pauseVideo&&p.pauseVideo()",null);web.onPause();super.onPause();}
 @Override protected void onDestroy(){active=null;handler.removeCallbacks(poll);io.shutdown();web.destroy();super.onDestroy();}
}
